        {
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Das Glück besteht darin, daß man da steht, wo man seiner Natur nach hingehört; selbst die Tugend- und Moralfrage verblaßt daneben.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Der Zauber steckt immer im Detail.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Die Dinge beobachten gilt mir beinah' mehr als sie besitzen, und so hat man schließlich seinen Glück- und Freudeertrag wie anscheinend Bevorzugtere.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Es gibt nur ein Mittel, sich wohl zu fühlen: Man muß lernen, mit dem Gegebenen zufrieden zu sein und nicht immer das verlangen, was gerade fehlt.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Es kommt immer nur drauf an, daß, wie und wo man auch marschirt, man allerorten die Musik des Lebens hört. Die meisten hören nur die Dissonanzen.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Ich hasse nicht die Könige, sondern den Druck, den sie mit sich führen.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Irgendwo kommt man immer auf seine Kosten.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Je älter ich werde, je mehr sehe ich ein: laufen lassen, wo nicht Amtspflicht das Gegenteil fordert, ist das allein Richtige.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Moral ist gut, Erbschaft ist besser.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Solange keine Wolken da sind, freue man sich des himmlischen Lichts.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Wer zu viel und zu scharf sieht, sieht auch falsch.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Abschiedsworte müssen kurz sein wie Liebeserklärungen.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Briefeschreiben ist wie Wetterleuchten; da verblitzt sich alles, und das Gewitter zieht nicht herauf.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Zwischen Hochmut und Demut steht ein drittes, dem das Leben gehört, und das ist der Mut.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Anstaunen ist auch eine Kunst. Es gehört etwas dazu, Großes als groß zu begreifen.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Courage ist gut, aber Ausdauer ist besser. Ausdauer, das ist die Hauptsache.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "»Frei, aber nicht frech«, das ist so mein Satz.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Übrigens darf ich bei allem Respekt vor meinem berühmten Hotel sagen, unberühmte sind meistens interessanter.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Wer ängstlich abwägt, sagt gar nichts. Nur die scharfe Zeichnung, die schon die Karikatur streift, macht eine Wirkung.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Wer demütig ist, der ist duldsam, weil er weiß, wie sehr er selbst der Duldsamkeit bedarf; wer demütig ist, der sieht die Scheidewände fallen und erblickt den Menschen im Menschen.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Ein weites Feld.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Jeder ist der Richtige. Natürlich muß er von Adel sein und eine Stellung haben und gut aussehen.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Und da war nun die Jugend wirklich allein.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Wer für den Strick geboren ist, wird im Wasser nicht umkommen.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Das Menschlichste, was wir haben, ist doch die Sprache.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Man muß sich untereinander helfen, das ist eigentlich das Beste von der Ehe. Sich helfen und unterstützen und vor allem nachsichtig sein und sich in das Recht des andern einleben. Denn was ist Recht? Es schwankt eigentlich immer. Aber Nachgiebigkeit, einem guten Menschen gegenüber, ist immer recht.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Von Jugend auf gepflegte Herzensbeziehungen sind doch das Schönste, was das Leben hat.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Was wäre das Leben ohne Liebesverhältnisse? Verstumpft, öde, langweilig.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Das Herz bleibt ein Kind.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Die Erfüllung eines Lieblingswunsches, sei der Wunsch selber, was er wolle, berührt uns wie eine Weihnachtsfreude.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Die Kunst soll nach Vollendung streben, soll ehrliche, gründliche Arbeit verrichten, und soweit dies die modernen »Impressionisten« tun, schließe ich auch diese Richtung innerhalb der Kunst von der Kunst selbst nicht aus.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Wer in der Mark reisen will, der muß zunächst Liebe zu \"Land und Leuten\" mitbringen, mindestens keine Voreingenommenheit. Er muß den guten Willen haben, das Gute zu finden, anstatt es durch krittliche Vergleiche totzumachen.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Alle Welt reist. So gewiss in alten Tagen eine Wetterunterhaltung war, so gewiss ist jetzt eine Reiseunterhaltung. »Wo waren Sie in diesem Sommer«, heißt es von Oktober bis Weihnachten; »wohin werden Sie sich im nächsten Sommer wenden?« heißt es von Weihnachten bis Ostern", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Das Poetische hat immer recht, es wächst weit über das Historische hinaus.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Der ist in tiefster Seele treu, wer die Heimat liebt wie du.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Erst der Ernst macht den Mann, erst der Fleiß das Genie.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Es kann die Ehre dieser Welt // dir keine Ehre geben. // Was dich in Wahrheit hebt und hält, // muss in dir selber leben.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Laß uns einen Rundgang machen, Leser, erst durch das Schiff der Kirche, wo der Kriegsruhm seine Lieblinge gebettet, oder einen Gedenkstein zur Erinnerung an die weitab Gefallenen errichtet hat.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Luft und Licht heilen und Ruhe heilt, aber den besten Balsam spendet doch ein gütiges Herz.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "O lerne denken mit dem Herzen, // Und lerne fühlen mit dem Geist.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Realismus ist die künstlerische Wiedergabe (nicht das bloße Abschreiben) des Lebens.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Solange es geht, muss man Milde walten lassen, denn jeder kann sie brauchen.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Tand, Tand, // Ist das Gebilde von Menschenhand!", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Wir kennen uns nie ganz, und über Nacht sind wir andre geworden, schlechter oder besser.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Wohl Keime wecken mag der Regen, // der in die Scholle niederbricht; // doch golden Korn und Erndtesegen // reift nur heran bei Sonnenlicht.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "..., in deren ganzem Verhalten sich die einzig wahre Bildung ausspräche, die Herzensbildung.", Author = "Theodor Fontane" },
            new Quote { Id = "https://de.wikiquote.org/wiki/Theodor_Fontane", Text = "Es wird wohl falsch zitiert sein; die meisten Zitate sind falsch.", Author = "Theodor Fontane" },
